//! A from-scratch URL parser mirroring the behaviour of the original C++
//! `url_parser` library.
//!
//! The parser is deliberately permissive: it never rejects input, it simply
//! splits a string into the components it can recognise and leaves the rest in
//! the path. See [`url_parser::URL`] for the component model.

pub mod url_parser;

pub use url_parser::URL;

