//! Emulation of `std::stoi` for the port field.

/// Lowest / highest values accepted as a port number.
const PORT_MIN: i64 = 0;
const PORT_MAX: i64 = 65535;

/// Sentinel returned when a URL carries no usable port.
pub const NO_PORT: i32 = -1;

/// Parses a port the way the C++ code does: `std::stoi` on the text following
/// the first `:` of the authority, keeping the result only when it lands inside
/// the valid port range.
///
/// `std::stoi` skips leading whitespace, accepts an optional sign and consumes
/// the longest digit prefix it can find, ignoring any trailing garbage. It
/// throws on a missing digit or on overflow; both cases surface here as
/// [`NO_PORT`], as does any in-range parse that falls outside `0..=65535`.
pub fn parse_port(text: &str) -> i32 {
    match stoi(text) {
        Some(value) if (PORT_MIN..=PORT_MAX).contains(&value) => value as i32,
        _ => NO_PORT,
    }
}

/// The `std::stoi` subset we need. `None` stands in for the exceptions
/// (`invalid_argument` and `out_of_range`) that the C++ side swallows.
fn stoi(text: &str) -> Option<i64> {
    let bytes = text.as_bytes();
    let mut i = 0;

    // `strtol` skips leading whitespace before anything else.
    while i < bytes.len() && is_space(bytes[i]) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    // At least one digit is required, otherwise `stoi` throws invalid_argument.
    let start = i;
    let mut magnitude: i64 = 0;
    while let Some(&byte) = bytes.get(i) {
        if !byte.is_ascii_digit() {
            break;
        }
        // Saturate rather than wrap: anything this large is out of range for a
        // port regardless of the exact value, which is all the caller checks.
        magnitude = magnitude
            .saturating_mul(10)
            .saturating_add(i64::from(byte - b'0'));
        i += 1;
    }
    if i == start {
        return None;
    }

    Some(if negative { -magnitude } else { magnitude })
}

/// `std::isspace` under the default C locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

