//! The splitting rules that carve a URL string into its components.
//!
//! Every helper here works on byte offsets found with ASCII delimiters, so the
//! resulting slices always land on `char` boundaries.

/// The separator that has to be present for a scheme (and therefore an
/// authority) to be recognised at all. A bare `scheme:` is *not* enough: such
/// input ends up entirely in the path.
pub const SCHEME_SEPARATOR: &str = "://";

/// Delimiters that terminate the authority and start the path/query/fragment.
const AUTHORITY_TERMINATORS: [char; 3] = ['/', '?', '#'];

/// Splits off the scheme, returning the lowercased scheme and the remainder
/// after `://`.
///
/// `None` means there was no `://` at all, in which case the caller must treat
/// the whole string as a path and skip authority parsing entirely.
pub fn split_scheme(input: &str) -> Option<(String, &str)> {
    let separator = input.find(SCHEME_SEPARATOR)?;
    let scheme = input[..separator].to_ascii_lowercase();
    Some((scheme, &input[separator + SCHEME_SEPARATOR.len()..]))
}

/// Splits the text following `://` into the authority and everything after it.
pub fn split_authority(rest: &str) -> (&str, &str) {
    match rest.find(AUTHORITY_TERMINATORS) {
        Some(end) => (&rest[..end], &rest[end..]),
        None => (rest, ""),
    }
}

/// Splits an authority into its userinfo and `host[:port]` halves.
///
/// The split happens at the *first* `@`, so `user@host@extra` yields a userinfo
/// of `user` and a host of `host@extra`.
pub fn split_userinfo(authority: &str) -> (&str, &str) {
    match authority.find('@') {
        Some(at) => (&authority[..at], &authority[at + 1..]),
        None => ("", authority),
    }
}

/// Splits `host[:port]` at the *first* `:`.
///
/// This is intentionally naive, matching the C++ implementation: a bracketed
/// IPv6 literal such as `[::1]:8080` is cut after `[`, leaving the rest to fail
/// port parsing.
pub fn split_host_port(host_port: &str) -> (&str, Option<&str>) {
    match host_port.find(':') {
        Some(colon) => (&host_port[..colon], Some(&host_port[colon + 1..])),
        None => (host_port, None),
    }
}

/// Peels the fragment off the end, at the first `#`.
pub fn split_fragment(rest: &str) -> (&str, &str) {
    match rest.find('#') {
        Some(hash) => (&rest[..hash], &rest[hash + 1..]),
        None => (rest, ""),
    }
}

/// Peels the query off the end, at the first `?`.
///
/// Runs *after* [`split_fragment`], which is why `path#frag?notquery` keeps the
/// `?notquery` inside the fragment.
pub fn split_query(rest: &str) -> (&str, &str) {
    match rest.find('?') {
        Some(mark) => (&rest[..mark], &rest[mark + 1..]),
        None => (rest, ""),
    }
}

