//! Entry point mirroring `tests/test18.cpp`: parses the URL given as the first
//! argument and prints every accessor, one per line.

use std::process::ExitCode;

use url_parser::URL;

/// Renders a bool the way `std::cout << bool` does, as `1` or `0`.
fn flag(value: bool) -> u8 {
    u8::from(value)
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        return ExitCode::from(1);
    }

    let url = &args[1];
    let parser = URL::new(url);

    // Test all getters
    println!("{}", parser.scheme());
    println!("{}", parser.authority());
    println!("{}", parser.userinfo());
    println!("{}", parser.host());
    println!("{}", parser.port());
    println!("{}", parser.path());
    println!("{}", parser.query());
    println!("{}", parser.fragment());

    // Test all has_* methods
    println!("{}", flag(parser.has_scheme()));
    println!("{}", flag(parser.has_authority()));
    println!("{}", flag(parser.has_userinfo()));
    println!("{}", flag(parser.has_host()));
    println!("{}", flag(parser.has_port()));
    println!("{}", flag(parser.has_path()));
    println!("{}", flag(parser.has_query()));
    println!("{}", flag(parser.has_fragment()));

    // Test to_string and is_valid
    println!("{}", parser.to_string());
    println!("{}", flag(parser.is_valid()));

    ExitCode::SUCCESS
}

