//! Component model for a parsed URL.

mod port;
mod split;

pub use port::NO_PORT;

use std::fmt;

/// A URL split into its RFC-3986-ish components.
///
/// Parsing never fails. Anything the parser cannot attribute to a scheme,
/// authority, query or fragment is left in the path, so a plain string like
/// `example.com` parses as a path-only URL.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct URL {
    scheme: String,
    userinfo: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    /// Parses `input` into its components.
    pub fn new(input: &str) -> Self {
        // The authority only exists when `://` is present; without it the whole
        // string is path-like, which is how `mailto:someone@example.com` ends up
        // as a bare path.
        let (scheme, authority, after_authority) = match split::split_scheme(input) {
            Some((scheme, rest)) => {
                let (authority, after_authority) = split::split_authority(rest);
                (scheme, authority, after_authority)
            }
            None => (String::new(), "", input),
        };

        let (userinfo, host_port) = split::split_userinfo(authority);
        let (host, port_text) = split::split_host_port(host_port);
        let port = port_text.map_or(NO_PORT, port::parse_port);

        // Fragment first, then query: a `?` after the `#` belongs to the
        // fragment, not to the query.
        let (before_fragment, fragment) = split::split_fragment(after_authority);
        let (path, query) = split::split_query(before_fragment);

        Self {
            scheme,
            userinfo: userinfo.to_string(),
            host: host.to_string(),
            port,
            path: path.to_string(),
            query: query.to_string(),
            fragment: fragment.to_string(),
        }
    }

    /// The scheme, lowercased, or empty when the input had no `://`.
    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    /// The authority, rebuilt from userinfo, host and port.
    ///
    /// This is a reconstruction rather than the original slice, so a port that
    /// failed to parse is simply dropped: `http://example.com:99999` reports an
    /// authority of `example.com`.
    pub fn authority(&self) -> String {
        let mut authority = String::new();
        if !self.userinfo.is_empty() {
            authority.push_str(&self.userinfo);
            authority.push('@');
        }
        authority.push_str(&self.host);
        if self.has_port() {
            authority.push(':');
            authority.push_str(&self.port.to_string());
        }
        authority
    }

    /// The userinfo (everything before the first `@` of the authority).
    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    /// The host (up to the first `:` of the authority).
    pub fn host(&self) -> &str {
        &self.host
    }

    /// The port, or [`NO_PORT`] when absent, unparseable or out of range.
    pub fn port(&self) -> i32 {
        self.port
    }

    /// The path.
    pub fn path(&self) -> &str {
        &self.path
    }

    /// The query, without the leading `?`.
    pub fn query(&self) -> &str {
        &self.query
    }

    /// The fragment, without the leading `#`.
    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    /// Whether an authority is present, which the C++ code decides purely from
    /// the host: `http://user@` has a non-empty [`URL::authority`] yet reports
    /// `false` here.
    pub fn has_authority(&self) -> bool {
        self.has_host()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port != NO_PORT
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    /// A URL counts as valid once it names either a host or a path.
    pub fn is_valid(&self) -> bool {
        self.has_host() || self.has_path()
    }
}

/// Reassembles the URL from its components; [`ToString::to_string`] mirrors the
/// C++ `to_string()`.
///
/// The authority is only emitted alongside a scheme, so an input like
/// `://example.com` — which parses to a host but no scheme — renders as the
/// empty string.
impl fmt::Display for URL {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.has_scheme() {
            write!(f, "{}{}{}", self.scheme, split::SCHEME_SEPARATOR, self.authority())?;
        }
        f.write_str(&self.path)?;
        if self.has_query() {
            write!(f, "?{}", self.query)?;
        }
        if self.has_fragment() {
            write!(f, "#{}", self.fragment)?;
        }
        Ok(())
    }
}

